import at.pinzker.taskloop.*;import java.util.*;import java.time.*;
public class ReminderDefaultsTests {
 static int count;static long ts(String s){return LocalDateTime.parse(s).atZone(ZoneId.of("Europe/Vienna")).toInstant().toEpochMilli();}static void check(boolean c,String label){count++;if(!c)throw new AssertionError(label);}
 public static void main(String[] a){TimeZone.setDefault(TimeZone.getTimeZone("Europe/Vienna"));check(ReminderDefaults.freeMinute(new int[0])==601,"first task 10:01");check(ReminderDefaults.freeMinute(new int[]{601})==602,"second task 10:02");check(ReminderDefaults.freeMinute(new int[]{601,603})==602,"first free slot");check(ReminderDefaults.freeMinute(new int[]{602,603})==601,"reuse free 10:01");check(ReminderDefaults.freeMinute(new int[]{600,601,601,720})==602,"custom times and duplicates");check(ReminderDefaults.nextWeekday(ts("2026-10-08T19:22:00"),new int[0])==ts("2026-10-09T10:01:00"),"Thursday to Friday");check(ReminderDefaults.nextWeekday(ts("2026-10-09T09:00:00"),new int[0])==ts("2026-10-09T10:01:00"),"Friday uses remaining time today");check(ReminderDefaults.nextWeekday(ts("2026-10-10T11:00:00"),new int[]{601})==ts("2026-10-12T10:02:00"),"Saturday skip Sunday");check(ReminderDefaults.nextWeekday(ts("2026-10-08T09:00:00"),new int[0])==ts("2026-10-08T10:01:00"),"Thursday uses remaining time today");check(ReminderDefaults.nextWeekday(ts("2026-10-08T11:00:00"),new int[0])==ts("2026-10-09T10:01:00"),"elapsed time moves to next workday");check(ReminderDefaults.nextWeekday(ts("2026-10-11T11:00:00"),new int[0])==ts("2026-10-12T10:01:00"),"Sunday to Monday");check(ReminderDefaults.nextWeekday(ts("2026-10-30T23:00:00"),new int[0])==ts("2026-11-02T10:01:00"),"month boundary");check(ReminderDefaults.nextWeekday(ts("2026-10-23T15:00:00"),new int[0])==ts("2026-10-26T10:01:00"),"DST weekend");check(ReminderDefaults.applyParsedTime(ts("2026-10-08T10:02:00"),ts("2026-10-09T18:00:00"),false,true,false)==ts("2026-10-09T10:02:00"),"explicit date keeps selected minute");check(ReminderDefaults.applyParsedTime(ts("2026-10-08T10:02:00"),ts("2026-10-09T18:00:00"),true,true,false)==ts("2026-10-09T18:00:00"),"explicit time wins");check(ReminderDefaults.applyParsedTime(ts("2026-10-08T10:02:00"),ts("2026-10-09T18:00:00"),false,false,false)==ts("2026-10-08T10:02:00"),"plain text retains defaults");TextParser.Result r=TextParser.parse("Morgen Rechnung prüfen",ts("2026-10-07T08:00:00"));check(r.hasDate&&!r.hasTime&&!r.hasRhythm,"date flags");r=TextParser.parse("Daily check invoice",ts("2026-10-07T08:00:00"),true);check(r.hasRhythm&&!r.hasTime&&!r.hasDate,"repeat preserves default time");r=TextParser.parse("Einkaufen",ts("2026-10-07T08:00:00"));check(!r.hasIgnore&&!r.hasPause,"plain input keeps rule defaults");System.out.println("PASS: "+count+" reminder default checks");}
}
